class Userinfo extends CI_Controller
{ public function __construct()
{
 parent::__construct();
$this->load->model('user_model');
}
public function index()
{
 // Check if the user is logged in and load their information
if ($this->session->userdata('logged_in')) {
$data['username'] = $this->session->userdata('username');
$data['profile_picture'] = $this->user_model->get_profile_picture($this->session->userdata('username'));
 // Load view to display user info
$this->load->view('header', $data);
$this->load->view('userinfo_view', $data);
$this->load->view('footer');
}
else {
redirect(base_url('login'), 'refresh');
}
}
public function update_profile()
{
if ($this->session->userdata('logged_in')) {
 // Get updated data from form input
$username = $this->input->post('username');
$profile_picture = $_FILES['profile_picture']['name'];
if (!empty($profile_picture)) {
move_uploaded_file($_FILES['profile_picture']['tmp_name'], 'uploads/' . $profile_picture);
}
else {
$profile_picture = $this->session->userdata('profile_picture');
}
 // Update user information in the database
$this->user_model->update_user_info($username, $profile_picture);
redirect(base_url('userinfo'), 'refresh');
}
else {
redirect(base_url('login'), 'refresh');
}
}
}
